# Template for Dds_Cfg.c source file
DDS_CFG_C_TEMPLATE = """/**
 * @file Dds_Cfg.c
 * @brief DDS Configuration Source
 * 
 * @warning This file is auto-generated by DDS Configuration Tool.
 *          Do not edit manually.
 */

#include "Dds_Cfg.h"
#include "Dds_TopicCfg.h"
#include "Dds_QosCfg.h"

/*==================================================================================================
*                                  TOPIC CONFIGURATION DATA
==================================================================================================*/

const Dds_TopicConfigType Dds_TopicConfigs[DDS_CFG_NUM_TOPIC_CONFIGS] =
{
{% for topic in topics %}
    { /* {{ topic.name }} */
        .topicId = DDS_TOPIC_ID_{{ topic.name | upper }},
        .kind = DDS_TOPIC_KIND_{{ topic.kind | default('STANDARD') }},
        .name = "{{ topic.name }}",
        .dataType = "{{ topic.data_type | default('void') }}",
        .maxInstances = {{ topic.max_instances | default(1) }}U,
        .e2eEnabled = {{ 'TRUE' if topic.security.e2e_enabled else 'FALSE' }},
        .e2eProfile = DDS_E2E_PROFILE_{{ topic.security.e2e_profile | default('P01') }},
        .e2eDataId = {{ topic.security.e2e_data_id | default(0) }}U
    },
{% endfor %}
};

/*==================================================================================================
*                                  QOS PROFILE DATA
==================================================================================================*/

{% for profile in qos_profiles %}
const Dds_QosProfileType Dds_QosProfile_{{ profile.name | upper }} =
{
    .reliability = {
        .kind = DDS_RELIABILITY_{{ profile.reliability.kind | default('RELIABLE') }},
        .maxBlockingTimeMs = {{ (profile.reliability.max_blocking_time | default(0.1) * 1000) | int }}U
    },
    .durability = {
        .kind = DDS_DURABILITY_{{ profile.durability.kind | default('VOLATILE') }}
    },
    .history = {
        .kind = DDS_HISTORY_{{ profile.history.kind | default('KEEP_LAST') }},
        .depth = {{ profile.history.depth | default(1) }}U
    },
    .liveliness = {
        .kind = DDS_LIVELINESS_{{ profile.liveliness.kind | default('AUTOMATIC') }},
        .leaseDurationSec = {{ profile.liveliness.lease_duration | default(10) | int }}U
    },
    .deadlineMs = {{ (profile.deadline.period | default(0) * 1000) | int }}U,
    .latencyBudgetMs = {{ (profile.latency_budget | default(0) * 1000) | int }}U,
    .transportPriority = {{ profile.transport_priority | default(0) }}U
};
{% endfor %}

/*==================================================================================================
*                                  MAIN CONFIGURATION
==================================================================================================*/

const Dds_ConfigType Dds_Config =
{
    .domainId = {{ domain_id | default(0) }}U,
    .numTopics = DDS_CFG_NUM_TOPIC_CONFIGS,
    .numTransports = DDS_CFG_NUM_TRANSPORTS,
    .topics = Dds_TopicConfigs,
    .transports = NULL
};

/* End of file */
"""

