class CodeTemplates:
    """Provides code generation templates."""
    
    TEMPLATES = {
        'dds_cfg_h': DDS_CFG_H_TEMPLATE,
        'dds_topic_cfg_h': DDS_TOPIC_CFG_H_TEMPLATE,
        'dds_qos_cfg_h': DDS_QOS_CFG_H_TEMPLATE,
        'dds_cfg_c': DDS_CFG_C_TEMPLATE,
        'bswm_dds_rules_h': BSWM_DDS_RULES_H_TEMPLATE,
        'e2e_cfg_h': E2E_CONFIG_TEMPLATE
    }
    
    @classmethod
    def get_template(cls, name: str) -> str:
        """Get template by name."""
        return cls.TEMPLATES.get(name, '')
    
    @classmethod
    def render(cls, name: str, context: dict) -> str:
        """Render template with context."""
        try:
            from jinja2 import Template
            template = Template(cls.get_template(name))
            return template.render(**context)
        except ImportError:
            # Simple string replacement fallback
            result = cls.get_template(name)
            for key, value in context.items():
                placeholder = '{{ ' + key + ' }}'
                result = result.replace(placeholder, str(value))
            return result
